/* sd_battle_overlay.c - host-side presentation overlay test mode.
 *
 * CycHostExtras.present implementation that composites a panel over the
 * normal game picture. Opt-in via CYC_HOST_EXTRAS build option; disabled by
 * default so normal presentation is untouched.
 *
 * Also hosts a project-local, experimental name-entry detector
 * (ne_detect.c/ne_detect.h). The detector runs every frame against the
 * ORIGINAL frame (cyc_frame_argb()) BEFORE any compositing, and is
 * re-evaluated each frame (no latching). A separate diagnostic option
 * (--name-entry-diag) draws "NAME ENTRY" in a small unused area only when
 * the detector matches. This is an English screen identifier, not a
 * transcription or translation of any Japanese label.
 *
 * A separate --english-ui option draws English labels over Japanese menu
 * labels on two screens:
 *   - name-entry (kana) screen: なまえ->NAME, もどる->BACK, おわり->DONE
 *   - character-selection screen: all 5 roster pages, each with its own
 *     label table and draw positions.
 * Each Japanese label rectangle is first covered with the surrounding
 * background (or black panel color for page 5), then the English text is
 * drawn. Erase geometry and English draw geometry are separate: moving
 * English text does not remove the original Japanese; only the erase
 * rectangle does.
 *
 * To avoid recursing through the presentation callback, the normal frame is
 * captured in frame_end() and the composed buffer is returned from present().
 *
 * Uses cyc_overlay_text() from the pinned engine (runner/cyc/cyc_overlay.c)
 * instead of a handmade font.
 */

#include "cyc_host_extras.h"
#include "cyc_overlay.h"
#include "cyc_render.h"
#include "ne_detect.h"
#include <stdlib.h>
#include <string.h>
#include <stdio.h>

/* ARGB8888 colors. */
#define PANEL_COLOR   0xFF000000u   /* opaque black panel (page 5 erase) */
#define TEXT_COLOR    0xFFFFFFFFu   /* opaque white text (page 5 draw) */
#define ENG_TEXT_COLOR 0x000000u    /* opaque black English label text */
#define BG_COLOR      0x00C0D8FFu   /* light blue screen background (192,216,255) */
#define PINK_COLOR    0xFFFF65A7u   /* pink outer background (255,101,167) */

/* Diagnostic text placement: small unused area near the bottom-left, clear
 * of the Japanese character grid (y ~120-188) and the entered-name field. */
#define NE_DIAG_X 10
#define NE_DIAG_Y 228

/* Measured English label rectangles on the name-entry (kana) screen.
 * Derived from the lossless name-entry references (ref_name_a.png,
 * ref_name_b.png), which are identical in the label area. Each rectangle is
 * the tight bounding box of one Japanese label's glyph pixels, verified
 * cursor-independent (identical across both cursor positions) and outside
 * the cursor/highlight areas. Each box contains only background and black
 * text pixels (no borders), so covering it with the background color removes
 * exactly the Japanese label pixels and preserves borders, highlights, and
 * the cursor.
 *
 * Label assignments (visually confirmed on the live screen):
 *   (96, 32, 31, 7) = なまえ -> NAME   (upper heading box, y ~32)
 *   (96, 92, 23, 11) = もどる -> BACK   (left grid control)
 *   (136, 96, 22, 7) = おわり -> DONE   (right grid control)
 *
 * Coordinates are valid only for the 256x240 native frame
 * (cyc_frame_argb()), never the composed/presented buffer.
 */
struct eng_label { int x, y, w, h; const char *text; int draw_x, draw_y; };

struct eng_label s_eng_labels[] = {
    { 96,  32, 31,  7, "NAME",  103, 33 },  /* なまえ: upper heading */
    { 96,  92, 23, 11, "BACK",  99,  95 },  /* もどる: left grid control */
    { 136, 96, 22,  7, "DONE",  139, 97 },  /* おわり: right grid control */
};
const int ENG_LABEL_COUNT = sizeof(s_eng_labels) / sizeof(s_eng_labels[0]);

