static int m78_team_identity_match(
    const uint32_t *frame,int w,int h)
{
    if (!frame || w!=256 || h!=240)
        return 0;

    size_t matched=0;
    const size_t count =
        sizeof(s_m78_identity)/sizeof(s_m78_identity[0]);

    for (size_t i=0;i<count;i++) {
        const M78IdentityPixel *p=&s_m78_identity[i];

        if (frame[(size_t)p->y*w+p->x]==p->color)
            matched++;
    }

    return matched*100>=count*95;
}
static void draw_m78_team_ui(
    uint32_t *out, int width, int height)
{
    if (!s_english_ui || !s_m78_team)
        return;

    const uint32_t black = 0xFF000000u;
    const uint32_t pink = 0xFFF5BDFFu;
    const uint32_t lower_bg = 0xFFF5BDFFu;
    const uint32_t white = 0xFFFFFFFFu;

    /* Determine which original M78 screen is displayed. */
    const uint32_t *original = cyc_frame_argb();

    int overview = ne_detect_m78_overview(original,256,240);
    int order = ne_detect_m78_order(original,256,240);

    if (!overview && !order)
        return;

    /* Main heading: erase original lettering at its location. */
    if (overview) {
        fill_rect(out,width,height,70,32,95,15,black);

        cyc_overlay_text(out,width,height,
                         82,36,1,0xF5BDFFu,
                         "THIS IS YOUR TEAM");
    }
    else {
        fill_rect(out,width,height,70,19,95,13,black);

        cyc_overlay_text(out,width,height,
                         91,23,1,0xF5BDFFu,
                         "CHOOSE THE ORDER!");
    }

    /* Left-side stable information. */
    fill_rect(out,width,height,15,67,49,13,black);
    fill_rect(out,width,height,55,87,33,9,black);
    fill_rect(out,width,height,55,115,33,13,black);

    cyc_overlay_text(out,width,height,
                     16,79,1,0xF5BDFFu,"M78 TEAM");

    cyc_overlay_text(out,width,height,
                     55,91,1,0xF5BDFFu,"MASTER");

    cyc_overlay_text(out,width,height,
                     55,122,1,0xF5BDFFu,"TSUBURAYA");

    /* Clear only the black interior of the orange panel.
     * The border occupies x=129..246 and remains untouched.
     */
    if (overview) {
        fill_rect(out,width,height,135,63,107,50,black);

        cyc_overlay_text(out,width,height,
                         139,75,1,0xF5BDFFu,
                         "FAVORITE ARENA:");

        cyc_overlay_text(out,width,height,
                         139,83,1,0xF5BDFFu,
                         "SPACE");

        cyc_overlay_text(out,width,height,
                         139,94,1,0xF5BDFFu,
                         "YOKOZUNA: TARO");

        cyc_overlay_text(out,width,height,
                         139,105,1,0xF5BDFFu,
                         "SEKIWAKE: ACE");
    }
    else {
        fill_rect(out,width,height,135,52,107,81,black);

        cyc_overlay_text(out,width,height,
                         139,65,1,0xF5BDFFu,
                         "PRESS B TO SET ORDER");

        cyc_overlay_text(out,width,height,
                         139,82,1,0xF5BDFFu,
                         "PRESS A TO CONFIRM");

        cyc_overlay_text(out,width,height,
                         139,99,1,0xF5BDFFu,
                         "BBBA = THIRD");
    }
    /* Bottom labels: preserve the pink background and portraits. */
    m78_erase_color(out,width,height,
                    0,210,256,19,white,lower_bg);

    cyc_overlay_text(out,width,height,
                     8,219,1,0xFFFFFFu,"ULTRAMAN");
    cyc_overlay_text(out,width,height,
                     69,219,1,0xFFFFFFu,"SEVEN");
    cyc_overlay_text(out,width,height,
                     116,219,1,0xFFFFFFu,"TARO");
    cyc_overlay_text(out,width,height,
                     172,219,1,0xFFFFFFu,"ACE");
    cyc_overlay_text(out,width,height,
                     212,219,1,0xFFFFFFu,"BALTAN");
}
