static void erase_dialogue_japanese(
    uint32_t *out, int width, int height)
{
    if (!out || width != 256 || height != 240)
        return;

    for (size_t i = 0;
         i < sizeof(s_dialogue_japanese_pixels) /
             sizeof(s_dialogue_japanese_pixels[0]);
         ++i) {
        int x = s_dialogue_japanese_pixels[i].x;
        int y = s_dialogue_japanese_pixels[i].y;
        uint32_t *pixel = &out[(size_t)y * width + x];

        if (*pixel == 0xFF179E00u)
            *pixel = 0xFFFFFFFFu;
    }
}
