static int bubble_match_ultraman_intro(
    const uint32_t *frame, int width, int height)
{
    if (!frame || width != 256 || height != 240)
        return 0;

    for (size_t i=0;
         i<sizeof(s_ultraman_intro)/sizeof(s_ultraman_intro[0]);
         ++i) {
        const BubblePixel *p = &s_ultraman_intro[i];

        if (frame[(size_t)p->y*width+p->x] != p->color)
            return 0;
    }

    return 1;
}

