static void bubble_clear_ultraman(
    uint32_t *out, int width, int height)
{
    if (!out || width != 256 || height != 240)
        return;

    for (size_t i=0;
         i<sizeof(s_ultraman_bubble_rows)/
           sizeof(s_ultraman_bubble_rows[0]);
         ++i) {
        const BubbleMaskRow *r = &s_ultraman_bubble_rows[i];

        for (int x=r->left; x<=r->right; ++x)
            out[(size_t)r->y*width+x] = 0xFFFFFFFFu;
    }
}
