static int bubble_match_right_variant(
    const uint32_t *frame, int width, int height,
    const RightBubblePixel *checks, size_t count)
{
    if (!frame || width != 256 || height != 240)
        return 0;

    for (size_t i=0; i<count; ++i) {
        const RightBubblePixel *p = &checks[i];

        if (frame[(size_t)p->y*width+p->x] != p->color)
            return 0;
    }

    return 1;
}

static void bubble_clear_right_variant(
    uint32_t *out, int width, int height,
    const RightBubbleRow *rows, size_t count)
{
    if (!out || width != 256 || height != 240)
        return;

    for (size_t i=0; i<count; ++i) {
        const RightBubbleRow *r = &rows[i];

        for (int x=r->left; x<=r->right; ++x)
            out[(size_t)r->y*width+x] = 0xFFFFFFFFu;
    }
}
