static int bubble_match_live_robo_text(
    const uint32_t *frame, int width, int height)
{
    if (!frame || width != 256 || height != 240)
        return 0;

    int matched = 0;

    for (size_t i=0;
         i<sizeof(s_live_robo_text)/sizeof(s_live_robo_text[0]);
         ++i) {
        const LiveRoboTextPixel *p = &s_live_robo_text[i];

        if (frame[(size_t)p->y*width+p->x] == 0xFF179E00u)
            matched++;
    }

    /* Require at least 95% of the reference text pixels. */
    return matched * 100 >=
           (int)(sizeof(s_live_robo_text)/sizeof(s_live_robo_text[0])) * 95;
}
