static int bubble_match_shadow_moon(
    const uint32_t *frame, int width, int height,
    const ShadowPixel *checks, size_t count)
{
    if (!frame || width != 256 || height != 240 || count == 0)
        return 0;

    size_t matched = 0;

    for (size_t i=0; i<count; ++i) {
        const ShadowPixel *p = &checks[i];

        if (frame[(size_t)p->y*width+p->x] == 0xFF179E00u)
            matched++;
    }

    return matched * 100 >= count * 95;
}

static void bubble_clear_shadow_moon(
    uint32_t *out, int width, int height,
    const ShadowRow *rows, size_t count)
{
    if (!out || width != 256 || height != 240)
        return;

    for (size_t i=0; i<count; ++i) {
        const ShadowRow *r = &rows[i];

        for (int x=r->left; x<=r->right; ++x)
            out[(size_t)r->y*width+x] = 0xFFFFFFFFu;
    }
}
typedef struct {
    unsigned short x,y;
} BatchIntroPixel;

typedef struct {
    unsigned short y,left,right;
} BatchIntroRow;

static int batch_intro_match(
    const uint32_t *frame,int w,int h,
    const BatchIntroPixel *pixels,size_t count)
{
    if (!frame || w!=256 || h!=240 || !count)
        return 0;

    size_t matched=0;
    for (size_t i=0;i<count;i++) {
        const BatchIntroPixel *p=&pixels[i];
        if (frame[(size_t)p->y*w+p->x]==0xFF179E00u)
            matched++;
    }
    return matched*100>=count*95;
}

static void batch_intro_clear(
    uint32_t *out,int w,int h,
    const BatchIntroRow *rows,size_t count)
{
    if (!out || w!=256 || h!=240)
        return;

    for (size_t i=0;i<count;i++) {
        const BatchIntroRow *r=&rows[i];
        for (int x=r->left;x<=r->right;x++)
            out[(size_t)r->y*w+x]=0xFFFFFFFFu;
    }
}
