typedef struct {
    unsigned short x,y;
} SDLowerPixel;

typedef struct {
    unsigned short y,left,right;
} SDLowerRow;

static int sd_lower_reuse_match(
    const uint32_t *frame,int w,int h,
    const SDLowerPixel *pixels,size_t count)
{
    if (!frame || w!=256 || h!=240 || !count)
        return 0;

    size_t matched=0;

    for (size_t i=0;i<count;i++) {
        const SDLowerPixel *p=&pixels[i];

        if (frame[(size_t)p->y*w+p->x]==0xFF179E00u)
            matched++;
    }

    return matched*100>=count*95;
}

static void sd_lower_reuse_clear(
    uint32_t *out,int w,int h,
    const SDLowerRow *rows,size_t count)
{
    if (!out || w!=256 || h!=240)
        return;

    for (size_t i=0;i<count;i++) {
        const SDLowerRow *r=&rows[i];

        for (int x=r->left;x<=r->right;x++)
            out[(size_t)r->y*w+x]=0xFFFFFFFFu;
    }
}
