static int rider_team_identity_match(
    const uint32_t *frame,int w,int h)
{
    if (!frame || w!=256 || h!=240)
        return 0;

    size_t matched=0;
    const size_t count =
        sizeof(s_rider_team_identity)/
        sizeof(s_rider_team_identity[0]);

    for (size_t i=0;i<count;i++) {
        const RiderTeamPixel *p=&s_rider_team_identity[i];

        if (frame[(size_t)p->y*w+p->x]==0xFFF5BDFFu)
            matched++;
    }

    return matched*100>=count*95;
}

static void draw_rider_team_ui(
    uint32_t *out,int width,int height)
{
    if (!s_english_ui || width!=256 || height!=240)
        return;

    const uint32_t *original=cyc_frame_argb();

    if (!rider_team_identity_match(original,256,240))
        return;

    const uint32_t black=0xFF000000u;
    const uint32_t pink=0xFFF5BDFFu;

    /* Main heading. */
    fill_rect(out,width,height,70,32,95,15,black);
    cyc_overlay_text(out,width,height,
                     82,36,1,0xF5BDFFu,
                     "THIS IS YOUR TEAM");

    /* Team name and stablemaster labels. */
    fill_rect(out,width,height,15,68,52,16,black);
    fill_rect(out,width,height,54,87,44,12,black);
    fill_rect(out,width,height,54,116,44,14,black);

    cyc_overlay_text(out,width,height,
                     16,79,1,0xF5BDFFu,"RIDER TEAM");

    cyc_overlay_text(out,width,height,
                     55,91,1,0xF5BDFFu,"MASTER");

    cyc_overlay_text(out,width,height,
                     55,122,1,0xF5BDFFu,"ISHINOMORI");

    /* Preserve the orange border and replace its text. */
    fill_rect(out,width,height,136,68,104,44,black);

    cyc_overlay_text(out,width,height,
                     139,75,1,0xF5BDFFu,
                     "FAVORITE ARENA:");

    cyc_overlay_text(out,width,height,
                     139,85,1,0xF5BDFFu,
                     "EARTH");

    cyc_overlay_text(out,width,height,
                     139,96,1,0xF5BDFFu,
                     "YOKOZUNA: RX");

    cyc_overlay_text(out,width,height,
                     139,106,1,0xF5BDFFu,
                     "SEKIWAKE: MOON");

    /* Bottom character labels. */
    fill_rect(out,width,height,0,210,256,19,pink);

    cyc_overlay_text(out,width,height,
                     8,219,1,0xFFFFFFu,"RIDER 1");
    cyc_overlay_text(out,width,height,
                     69,219,1,0xFFFFFFu,"RIDER 2");
    cyc_overlay_text(out,width,height,
                     121,219,1,0xFFFFFFu,"V3");
    cyc_overlay_text(out,width,height,
                     175,219,1,0xFFFFFFu,"RX");
    cyc_overlay_text(out,width,height,
                     207,219,1,0xFFFFFFu,"SHADOW MOON");
}
static void draw_rider_order_ui(
    uint32_t *out,int width,int height)
{
    if (!s_english_ui || width!=256 || height!=240)
        return;

    const uint32_t *original=cyc_frame_argb();

    if (!original)
        return;

    if (!rider_team_identity_match(original,256,240))
        return;

    /*
     * The order screen uses the upper heading at y=18..31.
     * The overview heading is at y=32..46.
     */
    const uint32_t pink=0xFFF5BDFFu;
    const uint32_t black=0xFF000000u;

    int orderHeading=0;

    for (int y=19;y<=30;y++) {
        for (int x=72;x<=160;x++) {
            if (original[(size_t)y*width+x]==pink)
                orderHeading++;
        }
    }

    if (orderHeading<35)
        return;

    /* Replace the original Japanese heading. */
    fill_rect(out,width,height,70,18,100,15,black);

    cyc_overlay_text(out,width,height,
                     91,23,1,0xF5BDFFu,
                     "CHOOSE THE ORDER!");

    /* Team identity. */
    fill_rect(out,width,height,15,68,52,16,black);
    fill_rect(out,width,height,54,87,44,12,black);
    fill_rect(out,width,height,54,116,44,14,black);

    cyc_overlay_text(out,width,height,
                     16,79,1,0xF5BDFFu,
                     "RIDER TEAM");

    cyc_overlay_text(out,width,height,
                     55,91,1,0xF5BDFFu,
                     "MASTER");

    cyc_overlay_text(out,width,height,
                     55,122,1,0xF5BDFFu,
                     "ISHINOMORI");

    /*
     * Replace only the black interior of the instruction
     * panel. Keep the orange patterned border intact.
     */
    fill_rect(out,width,height,136,68,104,62,black);

    cyc_overlay_text(out,width,height,
                     139,75,1,0xF5BDFFu,
                     "PRESS B FOR ORDER");

    cyc_overlay_text(out,width,height,
                     139,89,1,0xF5BDFFu,
                     "PRESS A TO SET");

    cyc_overlay_text(out,width,height,
                     139,103,1,0xF5BDFFu,
                     "BBBA = THIRD");

    /* Remove Japanese character labels and dakuten. */
    fill_rect(out,width,height,0,210,256,19,pink);

    cyc_overlay_text(out,width,height,
                     8,219,1,0xFFFFFFu,"RIDER 1");
    cyc_overlay_text(out,width,height,
                     69,219,1,0xFFFFFFu,"RIDER 2");
    cyc_overlay_text(out,width,height,
                     121,219,1,0xFFFFFFu,"V3");
    cyc_overlay_text(out,width,height,
                     175,219,1,0xFFFFFFu,"RX");
    cyc_overlay_text(out,width,height,
                     207,219,1,0xFFFFFFu,
                     "SHADOW MOON");
}
typedef struct {
    unsigned short x,y;
} SD0030Pixel;

typedef struct {
    unsigned short y,left,right;
} SD0030Row;

static int sd_dialogue_0030_match(
    const uint32_t *frame,int w,int h,
    const SD0030Pixel *pixels,size_t count)
{
    if (!frame || w!=256 || h!=240 || !count)
        return 0;

    size_t matched=0;

    for (size_t i=0;i<count;i++) {
        const SD0030Pixel *p=&pixels[i];

        if (frame[(size_t)p->y*w+p->x]==0xFF179E00u)
            matched++;
    }

    return matched*100>=count*95;
}

static void sd_dialogue_0030_clear(
    uint32_t *out,int w,int h,
    const SD0030Row *rows,size_t count)
{
    if (!out || w!=256 || h!=240)
        return;

    for (size_t i=0;i<count;i++) {
        const SD0030Row *r=&rows[i];

        for (int x=r->left;x<=r->right;x++)
            out[(size_t)r->y*w+x]=0xFFFFFFFFu;
    }
}
