/* Capture 0035: exact Japanese text-mask recognition. */
static uint32_t sd0035_region_hash(
    const uint32_t *frame,int w,
    int x0,int y0,int rw,int rh)
{
    uint32_t hash=5381u;

    for (int y=y0;y<y0+rh;y++) {
        for (int x=x0;x<x0+rw;x++) {
            uint32_t c=frame[(size_t)y*w+x];
            uint32_t bit=(c==0xFF179E00u) ? 1u : 0u;
            hash=hash*33u+bit;
        }
    }

    return hash;
}

static int sd0035_region_match(
    const uint32_t *frame,int w,int h,
    int x,int y,int rw,int rh,uint32_t expected)
{
    if (!frame || w!=256 || h!=240)
        return 0;

    if (x<0 || y<0 || x+rw>w || y+rh>h)
        return 0;

    return sd0035_region_hash(frame,w,x,y,rw,rh)==expected;
}

/* Erase only Japanese-green pixels on the white bubble interior. */
static void sd0035_clear(
    uint32_t *out,int w,int h,
    int x0,int y0,int rw,int rh)
{
    if (!out || w!=256 || h!=240)
        return;

    for (int y=y0;y<y0+rh;y++) {
        for (int x=x0;x<x0+rw;x++) {
            uint32_t *p=&out[(size_t)y*w+x];

            if (*p==0xFF179E00u || *p==0x00179E00u)
                *p=0xFFFFFFFFu;
        }
    }
}
/* Team 3: native-reference signatures (captures 0036-0038). */
static uint32_t team3_region_hash(const uint32_t *f,int w,int x0,int y0,int x1,int y1,int green_only) {
    uint32_t h=2166136261u;
    for(int y=y0;y<y1;y++) for(int x=x0;x<x1;x++) {
        uint32_t p=f[(size_t)y*w+x];
        uint32_t v=green_only ? (p==0xFF179E00u ? 1u : 0u) : (p&0x00FFFFFFu);
        h=(h^v)*16777619u;
    }
    return h;
}
static int team3_state(const uint32_t *f,int w,int h) {
    if(!f || w!=256 || h!=240 || f[0]!=0xFF000000u || f[(size_t)239*w+255]!=0xFFF5BDFFu) return 0;
    if(team3_region_hash(f,w,16,76,65,84,0)!=0x187666E9u) return 0;
    uint32_t head=team3_region_hash(f,w,70,18,170,49,0);
    if(head==0x3E0BA0EFu) return 1;
    if(head==0xEB3C8516u) return 2;
    return 0;
}
static void draw_team3_ui(uint32_t *out,int w,int h) {
    if(!s_english_ui || w!=256 || h!=240) return;
    int state=team3_state(cyc_frame_argb(),w,h);
    if(!state) return;
    const uint32_t black=0xFF000000u, pink=0xFFF5BDFFu;
    if(state==1) {
        fill_rect(out,w,h,70,32,100,15,black);
        cyc_overlay_text(out,w,h,82,36,1,0xF5BDFFu,"THIS IS YOUR TEAM");
    } else {
        fill_rect(out,w,h,70,18,100,15,black);
        cyc_overlay_text(out,w,h,91,23,1,0xF5BDFFu,"CHOOSE THE ORDER!");
    }
    fill_rect(out,w,h,15,68,52,16,black);
    fill_rect(out,w,h,54,87,44,12,black);
    fill_rect(out,w,h,54,116,44,14,black);
    cyc_overlay_text(out,w,h,16,79,1,0xF5BDFFu,"SENTAI TEAM");
    cyc_overlay_text(out,w,h,55,91,1,0xF5BDFFu,"MASTER");
    cyc_overlay_text(out,w,h,55,122,1,0xF5BDFFu,"WATANABE");
    if(state==1) {
        fill_rect(out,w,h,135,63,107,50,black);
        cyc_overlay_text(out,w,h,139,75,1,0xF5BDFFu,"FAVORITE ARENA:");
        cyc_overlay_text(out,w,h,139,83,1,0xF5BDFFu,"EARTH");
        cyc_overlay_text(out,w,h,139,94,1,0xF5BDFFu,"YOKOZUNA: LIVE ROBO");
        cyc_overlay_text(out,w,h,139,105,1,0xF5BDFFu,"SEKIWAKE: GREAT 5");
    } else {
        fill_rect(out,w,h,135,52,107,81,black);
        cyc_overlay_text(out,w,h,139,65,1,0xF5BDFFu,"PRESS B TO SET ORDER");
        cyc_overlay_text(out,w,h,139,82,1,0xF5BDFFu,"PRESS A TO CONFIRM");
        cyc_overlay_text(out,w,h,139,99,1,0xF5BDFFu,"BBBA = THIRD");
    }
    m78_erase_color(out,w,h,0,210,256,19,0xFFFFFFFFu,pink);
    cyc_overlay_text(out,w,h,4,219,1,0xFFFFFFu,"TURBO ROBO");
    cyc_overlay_text(out,w,h,57,219,1,0xFFFFFFu,"FLASH KING");
    cyc_overlay_text(out,w,h,111,219,1,0xFFFFFFu,"GREAT 5");
    cyc_overlay_text(out,w,h,159,219,1,0xFFFFFFu,"LIVE ROBO");
    cyc_overlay_text(out,w,h,215,219,1,0xFFFFFFu,"SILVA");
}
static void team3_silva_intro(uint32_t *out,int w,int h) {
    const uint32_t *orig=cyc_frame_argb();
    if(!orig || w!=256 || h!=240) return;
    if(team3_region_hash(orig,w,65,19,120,64,1)!=0x0747B83Fu) return;
    /* Erase only the interior green text; preserve white silhouette and pointer. */
    for(int y=20;y<=60;y++) {
        int left=-1,right=-1;
        for(int x=65;x<=119;x++) if(orig[(size_t)y*w+x]==0xFFFFFFFFu) {
            if(left<0) left=x;
            right=x;
        }
        if(left<0) continue;
        for(int x=left+1;x<right;x++) {
            uint32_t *p=&out[(size_t)y*w+x];
            if(*p==0xFF179E00u || *p==0x00179E00u) *p=0xFFFFFFFFu;
        }
    }
    cyc_overlay_text(out,w,h,75,39,1,0x00179E00u,"I'M SILVA!");
}
/* Capture 0040: exact native green-text region matching. */
static uint32_t sd0040_text_hash(
    const uint32_t *frame,int w,
    int x0,int y0,int rw,int rh)
{
    uint32_t hash=2166136261u;

    for(int y=y0;y<y0+rh;y++) {
        for(int x=x0;x<x0+rw;x++) {
            uint32_t p=frame[(size_t)y*w+x];
            uint32_t bit=(p==0xFF179E00u)?1u:0u;
            hash=(hash^bit)*16777619u;
        }
    }

    return hash;
}

static int sd0040_text_match(
    const uint32_t *frame,int w,int h,
    int x,int y,int rw,int rh,uint32_t expected)
{
    if(!frame || w!=256 || h!=240)
        return 0;

    if(x<0 || y<0 || x+rw>w || y+rh>h)
        return 0;

    return sd0040_text_hash(frame,w,x,y,rw,rh)==expected;
}

/* Clear original Japanese-green pixels, preserving white borders. */
static void sd0040_text_clear(
    uint32_t *out,const uint32_t *original,
    int w,int h,int x0,int y0,int rw,int rh)
{
    if(!out || !original || w!=256 || h!=240)
        return;

    for(int y=y0;y<y0+rh;y++) {
        for(int x=x0;x<x0+rw;x++) {
            size_t pos=(size_t)y*w+x;

            if(original[pos]==0xFF179E00u &&
               (out[pos]==0xFF179E00u ||
                out[pos]==0x00179E00u))
                out[pos]=0xFFFFFFFFu;
        }
    }
}
