static int team4_state(const uint32_t *f,int w,int h)
{
    if(!f || w!=256 || h!=240)
        return 0;

    if(f[0]!=0xFF000000u ||
       f[(size_t)239*w+255]!=0xFFF5BDFFu)
        return 0;

    if(team3_region_hash(f,w,16,76,65,84,0)!=0x804384E4u)
        return 0;

    uint32_t heading=team3_region_hash(
        f,w,70,18,170,49,0);

    if(heading==0x3E0BA0EFu) return 1;
    if(heading==0xEB3C8516u) return 2;

    return 0;
}

static void draw_team4_ui(uint32_t *out,int w,int h)
{
    if(!s_english_ui || w!=256 || h!=240)
        return;

    int state=team4_state(cyc_frame_argb(),w,h);

    if(!state)
        return;

    const uint32_t black=0xFF000000u;
    const uint32_t pink=0xFFF5BDFFu;

    if(state==1) {
        fill_rect(out,w,h,70,32,100,15,black);
        cyc_overlay_text(out,w,h,82,36,1,0xF5BDFFu,
                         "THIS IS YOUR TEAM");
    }
    else {
        fill_rect(out,w,h,70,18,100,15,black);
        cyc_overlay_text(out,w,h,91,23,1,0xF5BDFFu,
                         "CHOOSE THE ORDER!");
    }

    /* Team identity and stablemaster. */
    fill_rect(out,w,h,15,68,52,16,black);
    fill_rect(out,w,h,54,87,44,12,black);
    fill_rect(out,w,h,54,116,44,14,black);

    cyc_overlay_text(out,w,h,16,79,1,0xF5BDFFu,
                     "MS TEAM");
    cyc_overlay_text(out,w,h,55,91,1,0xF5BDFFu,
                     "MASTER");
    cyc_overlay_text(out,w,h,55,122,1,0xF5BDFFu,
                     "TOMINO");

    if(state==1) {
        /* Team overview panel. */
        fill_rect(out,w,h,135,63,107,50,black);

        cyc_overlay_text(out,w,h,139,75,1,0xF5BDFFu,
                         "FAVORITE ARENA:");
        cyc_overlay_text(out,w,h,139,83,1,0xF5BDFFu,
                         "SPACE");
        cyc_overlay_text(out,w,h,139,94,1,0xF5BDFFu,
                         "YOKOZUNA: NU GUNDAM");
        cyc_overlay_text(out,w,h,139,105,1,0xF5BDFFu,
                         "SEKIWAKE: HYAKU SHIKI");
    }
    else {
        /* Character-order instructions. */
        fill_rect(out,w,h,135,52,107,81,black);

        cyc_overlay_text(out,w,h,139,65,1,0xF5BDFFu,
                         "PRESS B TO SET ORDER");
        cyc_overlay_text(out,w,h,139,82,1,0xF5BDFFu,
                         "PRESS A TO CONFIRM");
        cyc_overlay_text(out,w,h,139,99,1,0xF5BDFFu,
                         "BBBA = THIRD");
    }

    /* Clear Japanese names and dakuten. */
    m78_erase_color(out,w,h,0,210,256,19,
                    0xFFFFFFFFu,pink);

    cyc_overlay_text(out,w,h,23,219,1,0xFFFFFFu,
                     "ALEX");
    cyc_overlay_text(out,w,h,67,219,1,0xFFFFFFu,
                     "MK-II");
    cyc_overlay_text(out,w,h,107,219,1,0xFFFFFFu,
                     "NU GUNDAM");
    cyc_overlay_text(out,w,h,158,219,1,0xFFFFFFu,
                     "HYAKU SHIKI");
    cyc_overlay_text(out,w,h,216,219,1,0xFFFFFFu,
                     "ZEONG");
}

/* Zeong's independent top-left introduction. */
static void team4_zeong_intro(
    uint32_t *out,int w,int h)
{
    if(!s_english_ui || !s_green_dialogue)
        return;

    const uint32_t *orig=cyc_frame_argb();

    if(!orig || w!=256 || h!=240)
        return;

    if(team3_region_hash(orig,w,65,19,120,64,1)!=0xAEFCA10Fu)
        return;

    /* Erase only green text inside the white bubble. */
    for(int y=20;y<=62;y++) {
        int left=-1,right=-1;

        for(int x=65;x<=119;x++) {
            if(orig[(size_t)y*w+x]==0xFFFFFFFFu) {
                if(left<0) left=x;
                right=x;
            }
        }

        if(left<0 || right-left<10)
            continue;

        for(int x=left+1;x<right;x++) {
            size_t pos=(size_t)y*w+x;

            if(orig[pos]==0xFF179E00u &&
               (out[pos]==0xFF179E00u ||
                out[pos]==0x00179E00u))
                out[pos]=0xFFFFFFFFu;
        }
    }

    cyc_overlay_text(out,w,h,73,36,1,0x00179E00u,
                     "I'M ZEONG!");
    cyc_overlay_text(out,w,h,77,47,1,0x00179E00u,
                     "COME ON!");
}
/* Capture 0046: alternative Great Five introduction. */
static int sd0046_greatfive_match(
    const uint32_t *frame,int w,int h)
{
    if(!frame || w!=256 || h!=240)
        return 0;

    uint32_t hash=2166136261u;

    for(int y=19;y<64;y++) {
        for(int x=65;x<120;x++) {
            uint32_t p=frame[(size_t)y*w+x];
            uint32_t bit=(p==0xFF179E00u)?1u:0u;
            hash=(hash^bit)*16777619u;
        }
    }

    return hash==0x98179DB7u;
}

