/* Capture 0066: Nu Gundam versus Ultraseven. */

static uint32_t sd0066_green_hash(
    const uint32_t *f,int w,
    int x0,int y0,int x1,int y1)
{
    uint32_t hash=2166136261u;

    for(int y=y0;y<y1;y++) {
        for(int x=x0;x<x1;x++) {
            uint32_t p=f[(size_t)y*w+x];
            uint32_t bit=(p==0xFF179E00u)?1u:0u;
            hash=(hash^bit)*16777619u;
        }
    }

    return hash;
}

static void sd0066_clear_green(
    uint32_t *out,const uint32_t *orig,int w,
    int x0,int y0,int x1,int y1)
{
    for(int y=y0;y<y1;y++) {
        for(int x=x0;x<x1;x++) {
            size_t p=(size_t)y*w+x;

            if(orig[p]==0xFF179E00u)
                out[p]=0xFFFFFFFFu;
        }
    }
}

static void sd0066_nugundam_ui(
    uint32_t *out,int w,int h)
{
    if(!s_english_ui || !out || w!=256 || h!=240)
        return;

    const uint32_t *orig=cyc_frame_argb();

    if(!orig)
        return;

    uint32_t top=sd0066_green_hash(
        orig,w,65,19,120,64);

    uint32_t bottom=sd0066_green_hash(
        orig,w,8,108,57,221);

    if(top==0xEBC16A30u) {
        sd0066_clear_green(
            out,orig,w,65,19,120,64);

        cyc_overlay_text(
            out,w,h,72,36,1,0x00179E00u,
            "NU GUNDAM");

        cyc_overlay_text(
            out,w,h,77,47,1,0x00179E00u,
            "LAUNCHING!");
    }

    if(bottom==0x6CE1B669u) {
        sd0066_clear_green(
            out,orig,w,8,108,57,221);

        cyc_overlay_text(
            out,w,h,20,143,1,0x00179E00u,
            "SO YOU'RE");

        cyc_overlay_text(
            out,w,h,20,154,1,0x00179E00u,
            "MY OPPONENT?");

        cyc_overlay_text(
            out,w,h,20,165,1,0x00179E00u,
            "I WON'T STOP!");
    }
}
